// "Team & alerts" tab: who can use the studio admin and who receives booking emails.
(()=>{
 const tab=document.createElement('button');tab.dataset.tab='team';tab.textContent='Team & alerts';tab.setAttribute('aria-pressed','false');document.querySelector('.tabs').append(tab);
 const panel=document.createElement('section');panel.id='team';panel.hidden=true;
 panel.innerHTML=`<h2>Team & booking alerts</h2>
<p>Everyone on this list can sign in to this studio admin, and people with <b>booking emails</b> on get an email for every new request. To hand the studio to someone else, add their email here, ask them to create their login, then remove yourself if you wish.</p>
<form id="team-form" class="card" style="margin:18px 0"><h3 style="margin-top:0">Add a person</h3><div class="toolbar"><input id="team-email" type="email" required placeholder="name@example.com" aria-label="Email address" style="flex:3"><label class="toggle" style="flex:none;white-space:nowrap"><input id="team-alerts" type="checkbox" checked> Send them booking emails</label><button>Add person</button></div><p class="muted" style="margin-bottom:0">They then open this admin page, enter this email, choose <b>Create admin login</b> and confirm the email they receive.</p></form>
<p id="team-status" class="status" role="status"></p>
<div id="team-list" class="cards"></div>
<p class="notice"><b>Email delivery note:</b> booking emails are sent through Resend. Until a domain (e.g. glowbloom.co.zm) is verified in Resend, Resend only delivers to the email address that owns the Resend account. To email other people, verify a domain in Resend, or have the new owner create their own Resend account and replace <code>RESEND_API_KEY</code> in Vercel.</p>`;
 document.querySelector('#dashboard').append(panel);
 const ids=['appointments','treatments','content','analytics','team'];
 document.querySelectorAll('[data-tab]').forEach(b=>{const prev=b.onclick;b.onclick=e=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));ids.forEach(id=>{const el=document.getElementById(id);if(el)el.hidden=b.dataset.tab!==id});if(b.dataset.tab==='analytics'&&prev)prev.call(b,e);if(b===tab)load()}});
 const status=t=>document.getElementById('team-status').textContent=t;
 async function rpc(name,body){const access=await token();const r=await fetch(API+'/rest/v1/rpc/'+name,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+access,'Content-Type':'application/json'},body:JSON.stringify(body||{}),signal:AbortSignal.timeout(15000)});const data=r.status===204?null:await r.json().catch(()=>null);if(!r.ok)throw Error(data?.message||'Could not complete the request.');return data}
 async function load(){status('Loading team…');try{const rows=await rpc('bloom_team');document.getElementById('team-list').innerHTML=rows.map(r=>`<article class="card"><h3 style="margin-bottom:6px">${esc(r.email)}</h3><div class="meta">${r.is_admin?'✓ Can use studio admin':r.signed_up?'Signed up, waiting for approval: refresh shortly':'Not signed up yet: ask them to choose “Create admin login” on this page'}</div><div class="row"><label class="toggle"><input type="checkbox" data-alerts="${esc(r.email)}" ${r.receives_alerts?'checked':''}> Booking emails</label><button class="secondary" data-remove="${esc(r.email)}">Remove</button></div></article>`).join('')||'<p>No team members yet.</p>';status('')}catch(err){status(err.message)}}
 document.getElementById('team-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await rpc('bloom_team_add',{p_email:document.getElementById('team-email').value,p_alerts:document.getElementById('team-alerts').checked});document.getElementById('team-email').value='';await load();status('Added. Ask them to create their admin login with this email.')}catch(err){status(err.message)}finally{b.disabled=false}};
 document.getElementById('team-list').onchange=async e=>{const c=e.target.closest('[data-alerts]');if(!c)return;c.disabled=true;try{await rpc('bloom_team_alerts',{p_email:c.dataset.alerts,p_alerts:c.checked});status(c.checked?'Booking emails turned on.':'Booking emails turned off.')}catch(err){c.checked=!c.checked;status(err.message)}finally{c.disabled=false}};
 document.getElementById('team-list').onclick=async e=>{const b=e.target.closest('[data-remove]');if(!b)return;if(b.dataset.confirm!=='1'){b.dataset.confirm='1';b.textContent='Tap again to remove';return}b.disabled=true;try{await rpc('bloom_team_remove',{p_email:b.dataset.remove});await load();status('Removed. They can no longer use the studio admin or receive booking emails.')}catch(err){status(err.message);b.disabled=false}};
})();
